create or replace package apx_mbms_sec_pkg as
   /**
    * Versi package (format XX.YY.ZZ).
    * @return versi
    */
   function package_version return varchar2;

   /**
    * User aktif: APP_USER di sesi APEX, SESSION_USER di luar APEX.
    * @return username (uppercase)
    */
   function app_user return varchar2;

   /**
    * Mode bootstrap: TRUE selama belum ada user ber-role ADMIN.
    * @return TRUE bila belum ada ADMIN
    */
   function bootstrap_mode return boolean;

   /**
    * Apakah user memiliki role (ADMIN selalu lolos; bootstrap -> semua lolos).
    * @param p_role      kode role
    * @param p_username  username, default user aktif
    * @return TRUE bila memiliki role
    */
   function has_role (
      p_role     in varchar2
     ,p_username in varchar2 default null
   ) return boolean;

   /**
    * Versi Y/N dari has_role, untuk dipakai di SQL.
    * @param p_role      kode role
    * @param p_username  username, default user aktif
    * @return 'Y' atau 'N'
    */
   function has_role_yn (
      p_role     in varchar2
     ,p_username in varchar2 default null
   ) return varchar2;

   /**
    * Apakah user terdaftar (punya minimal satu role) atau mode bootstrap.
    * @param p_username  username, default user aktif
    * @return TRUE bila terdaftar
    */
   function has_any_role (
      p_username in varchar2 default null
   ) return boolean;

   /**
    * HANYA untuk unit test di luar APEX: override user aktif.
    * @param p_username  username, null untuk reset
    */
   procedure set_test_user (
      p_username in varchar2
   );
end apx_mbms_sec_pkg;
/

create or replace package body apx_mbms_sec_pkg as

   g_test_user varchar2(255);

   function package_version return varchar2
   is
   begin
      -- Version History:
      -- 01.00.00 2026-11-01 Tim PANDAWA  Generated by pandawa-apexlang
      return '01.00.00';
   end package_version;

   function app_user return varchar2
   is
   begin
      return upper(coalesce(g_test_user
                           ,sys_context('APEX$SESSION', 'APP_USER')
                           ,sys_context('USERENV', 'SESSION_USER')));
   end app_user;

   function bootstrap_mode return boolean
   is
      l_count number;
   begin
      select count(*)
        into l_count
        from apx_mbms_user_roles
       where role_code = 'ADMIN';
      return l_count = 0;
   end bootstrap_mode;

   function has_role (
      p_role     in varchar2
     ,p_username in varchar2 default null
   ) return boolean
   is
      l_user  apx_mbms_user_roles.username%type := upper(coalesce(p_username, app_user));
      l_count number;
   begin
      if bootstrap_mode then
         return true;
      end if;
      select count(*)
        into l_count
        from apx_mbms_user_roles
       where username = l_user
         and role_code in (upper(p_role), 'ADMIN');
      return l_count > 0;
   end has_role;

   function has_role_yn (
      p_role     in varchar2
     ,p_username in varchar2 default null
   ) return varchar2
   is
   begin
      return case when has_role(p_role, p_username) then 'Y' else 'N' end;
   end has_role_yn;

   function has_any_role (
      p_username in varchar2 default null
   ) return boolean
   is
      l_user  apx_mbms_user_roles.username%type := upper(coalesce(p_username, app_user));
      l_count number;
   begin
      if bootstrap_mode then
         return true;
      end if;
      select count(*)
        into l_count
        from apx_mbms_user_roles
       where username = l_user;
      return l_count > 0;
   end has_any_role;

   procedure set_test_user (
      p_username in varchar2
   )
   is
   begin
      g_test_user := upper(p_username);
   end set_test_user;

end apx_mbms_sec_pkg;
/

create or replace package apx_mbms_doc_pkg as
   /**
    * Versi package (format XX.YY.ZZ).
    * @return versi
    */
   function package_version return varchar2;

   /**
    * Nomor dokumen berikutnya: PREFIX-YYYY-NNNN (prefix dari apx_mbms_doc_types).
    * @param p_doc_type  jenis dokumen
    * @param p_date      tanggal dokumen (menentukan periode)
    * @return nomor dokumen
    */
   function next_no (
      p_doc_type in varchar2
     ,p_date     in date default sysdate
   ) return varchar2;
end apx_mbms_doc_pkg;
/

create or replace package body apx_mbms_doc_pkg as

   function package_version return varchar2
   is
   begin
      -- Version History:
      -- 01.00.00 2026-11-01 Tim PANDAWA  Generated by pandawa-apexlang
      return '01.00.00';
   end package_version;

   function next_no (
      p_doc_type in varchar2
     ,p_date     in date default sysdate
   ) return varchar2
   is
      l_prefix apx_mbms_doc_types.prefix%type;
      l_period apx_mbms_doc_seq.period%type := to_char(nvl(p_date, sysdate), 'YYYY');
      l_no     apx_mbms_doc_seq.last_no%type;
   begin
      select prefix
        into l_prefix
        from apx_mbms_doc_types
       where doc_type = p_doc_type;

      merge into apx_mbms_doc_seq s
      using (select p_doc_type doc_type
                   ,l_period   period
               from dual) n
         on (s.doc_type = n.doc_type and s.period = n.period)
       when not matched then
            insert (doc_type, period, last_no)
            values (n.doc_type, n.period, 0);

      update apx_mbms_doc_seq
         set last_no = last_no + 1
       where doc_type = p_doc_type
         and period   = l_period
      returning last_no into l_no;

      return l_prefix || '-' || l_period || '-' || lpad(l_no, 4, '0');
   end next_no;

end apx_mbms_doc_pkg;
/

create or replace package apx_mbms_approval_pkg as
   /**
    * Versi package (format XX.YY.ZZ).
    * @return versi
    */
   function package_version return varchar2;

   /**
    * TRUE saat perubahan status sedang dilakukan oleh package ini (dipakai trigger guard).
    * @return status bypass
    */
   function bypass return boolean;

   /**
    * Set bypass (untuk seed/migrasi data). Selalu kembalikan ke FALSE setelah selesai.
    * @param p_value  nilai bypass
    */
   procedure set_bypass (
      p_value in boolean
   );

   /**
    * Nilai dokumen untuk aturan approval (amount_expr di apx_mbms_doc_types).
    * @param p_doc_type  jenis dokumen
    * @param p_doc_id    id dokumen
    * @return nilai
    */
   function doc_amount (
      p_doc_type in varchar2
     ,p_doc_id   in number
   ) return number;

   /**
    * Ajukan dokumen DRAFT/REJECTED untuk approval.
    * @param p_doc_type  jenis dokumen
    * @param p_doc_id    id dokumen
    * @throws -20101..-20109  aturan approval dilanggar
    */
   procedure submit (
      p_doc_type in varchar2
     ,p_doc_id   in number
   );

   /**
    * Setujui satu langkah approval (maker-checker, cek role).
    * @param p_approval_id  id approval
    * @param p_note         catatan
    */
   procedure approve (
      p_approval_id in number
     ,p_note        in varchar2 default null
   );

   /**
    * Tolak satu langkah approval (catatan wajib).
    * @param p_approval_id  id approval
    * @param p_note         alasan penolakan
    */
   procedure reject (
      p_approval_id in number
     ,p_note        in varchar2
   );

   /**
    * Apakah user aktif boleh memproses approval ini.
    * @param p_approval_id  id approval
    * @return 'Y' atau 'N'
    */
   function can_act_yn (
      p_approval_id in number
   ) return varchar2;
end apx_mbms_approval_pkg;
/

create or replace package body apx_mbms_approval_pkg as

   k_draft     constant varchar2(20) := 'DRAFT';
   k_submitted constant varchar2(20) := 'SUBMITTED';
   k_approved  constant varchar2(20) := 'APPROVED';
   k_rejected  constant varchar2(20) := 'REJECTED';
   k_pending   constant varchar2(20) := 'PENDING';

   g_bypass boolean := false;

   function package_version return varchar2
   is
   begin
      -- Version History:
      -- 01.00.00 2026-11-01 Tim PANDAWA  Generated by pandawa-apexlang
      return '01.00.00';
   end package_version;

   function bypass return boolean
   is
   begin
      return g_bypass;
   end bypass;

   procedure set_bypass (
      p_value in boolean
   )
   is
   begin
      g_bypass := p_value;
   end set_bypass;

   function get_type (
      p_doc_type in varchar2
   ) return apx_mbms_doc_types%rowtype
   is
      r_type apx_mbms_doc_types%rowtype;
   begin
      select *
        into r_type
        from apx_mbms_doc_types
       where doc_type = p_doc_type;
      return r_type;
   exception
      when no_data_found then
         raise_application_error(-20100, 'Jenis dokumen ' || p_doc_type || ' tidak dikenal.');
   end get_type;

   procedure get_doc (
      r_type   in  apx_mbms_doc_types%rowtype
     ,p_doc_id in  number
     ,x_doc_no out varchar2
     ,x_status out varchar2
   )
   is
   begin
      execute immediate
            'select ' || dbms_assert.simple_sql_name(r_type.number_column)
         || '      ,' || dbms_assert.simple_sql_name(r_type.status_column)
         || '  from ' || dbms_assert.simple_sql_name(r_type.table_name)
         || ' where ' || dbms_assert.simple_sql_name(r_type.pk_column) || ' = :id'
         into x_doc_no, x_status
        using p_doc_id;
   end get_doc;

   procedure set_doc_status (
      r_type   in apx_mbms_doc_types%rowtype
     ,p_doc_id in number
     ,p_status in varchar2
   )
   is
   begin
      g_bypass := true;
      execute immediate
            'update ' || dbms_assert.simple_sql_name(r_type.table_name)
         || '   set ' || dbms_assert.simple_sql_name(r_type.status_column) || ' = :status'
         || ' where ' || dbms_assert.simple_sql_name(r_type.pk_column) || ' = :id'
        using p_status, p_doc_id;
      g_bypass := false;
   exception
      when others then
         g_bypass := false;
         raise;
   end set_doc_status;

   function doc_amount (
      p_doc_type in varchar2
     ,p_doc_id   in number
   ) return number
   is
      r_type   apx_mbms_doc_types%rowtype := get_type(p_doc_type);
      l_amount number;
   begin
      if r_type.amount_expr is null then
         return 0;
      end if;
      -- amount_expr adalah konfigurasi generator (bukan input user)
      execute immediate
            'select ' || r_type.amount_expr
         || '  from ' || dbms_assert.simple_sql_name(r_type.table_name) || ' t'
         || ' where t.' || dbms_assert.simple_sql_name(r_type.pk_column) || ' = :id'
         into l_amount
        using p_doc_id;
      return nvl(l_amount, 0);
   end doc_amount;

   procedure create_step (
      r_type         in apx_mbms_doc_types%rowtype
     ,p_doc_id       in number
     ,p_level        in number
     ,p_role         in varchar2
     ,p_requested_by in varchar2
   )
   is
      l_doc_no varchar2(100);
      l_status varchar2(30);
   begin
      get_doc(r_type, p_doc_id, l_doc_no, l_status);
      insert into apx_mbms_approvals (
         doc_type
        ,doc_id
        ,doc_no
        ,approval_level
        ,approver_role
        ,amount
        ,requested_by
        ,requested_on
        ,status
      ) values (
         r_type.doc_type
        ,p_doc_id
        ,l_doc_no
        ,p_level
        ,p_role
        ,doc_amount(r_type.doc_type, p_doc_id)
        ,p_requested_by
        ,sysdate
        ,k_pending
      );
   end create_step;

   procedure submit (
      p_doc_type in varchar2
     ,p_doc_id   in number
   )
   is
      r_type   apx_mbms_doc_types%rowtype := get_type(p_doc_type);
      l_doc_no varchar2(100);
      l_status varchar2(30);
   begin
      get_doc(r_type, p_doc_id, l_doc_no, l_status);
      if l_status not in (k_draft, k_rejected) then
         raise_application_error(-20101, 'Dokumen ' || l_doc_no || ' berstatus ' || l_status || ' dan tidak dapat diajukan.');
      end if;

      -- validasi khusus jenis dokumen (mis. budget check), procedure (p_doc_id in number)
      if r_type.validate_proc is not null then
         execute immediate 'begin ' || dbms_assert.qualified_sql_name(r_type.validate_proc) || '(:id); end;'
           using p_doc_id;
      end if;

      if r_type.approver1_role is null then
         set_doc_status(r_type, p_doc_id, k_approved);
      else
         set_doc_status(r_type, p_doc_id, k_submitted);
         create_step(r_type, p_doc_id, 1, r_type.approver1_role, apx_mbms_sec_pkg.app_user);
      end if;
   end submit;

   function can_act_yn (
      p_approval_id in number
   ) return varchar2
   is
      r_appr apx_mbms_approvals%rowtype;
   begin
      select *
        into r_appr
        from apx_mbms_approvals
       where approval_id = p_approval_id;
      if r_appr.status <> k_pending
         or upper(r_appr.requested_by) = apx_mbms_sec_pkg.app_user
      then
         return 'N';
      end if;
      return apx_mbms_sec_pkg.has_role_yn(r_appr.approver_role);
   exception
      when no_data_found then
         return 'N';
   end can_act_yn;

   procedure assert_can_act (
      r_appr in apx_mbms_approvals%rowtype
   )
   is
   begin
      if r_appr.status <> k_pending then
         raise_application_error(-20105, 'Approval ini sudah diproses (' || r_appr.status || ').');
      end if;
      if upper(r_appr.requested_by) = apx_mbms_sec_pkg.app_user then
         raise_application_error(-20106, 'Segregation of duties: pengaju tidak boleh menyetujui dokumennya sendiri.');
      end if;
      if not apx_mbms_sec_pkg.has_role(r_appr.approver_role) then
         raise_application_error(-20107, 'Anda tidak memiliki role ' || r_appr.approver_role || ' untuk approval ini.');
      end if;
   end assert_can_act;

   procedure approve (
      p_approval_id in number
     ,p_note        in varchar2 default null
   )
   is
      r_appr apx_mbms_approvals%rowtype;
      r_type apx_mbms_doc_types%rowtype;
   begin
      select *
        into r_appr
        from apx_mbms_approvals
       where approval_id = p_approval_id
         for update;
      assert_can_act(r_appr);

      update apx_mbms_approvals
         set status   = k_approved
            ,acted_by = apx_mbms_sec_pkg.app_user
            ,acted_on = sysdate
            ,note     = p_note
       where approval_id = p_approval_id;

      r_type := get_type(r_appr.doc_type);
      if r_appr.approval_level = 1
         and r_type.approver2_role is not null
         and nvl(r_appr.amount, 0) > r_type.level2_limit
      then
         create_step(r_type, r_appr.doc_id, 2, r_type.approver2_role, r_appr.requested_by);
      else
         set_doc_status(r_type, r_appr.doc_id, k_approved);
      end if;
   end approve;

   procedure reject (
      p_approval_id in number
     ,p_note        in varchar2
   )
   is
      r_appr apx_mbms_approvals%rowtype;
   begin
      select *
        into r_appr
        from apx_mbms_approvals
       where approval_id = p_approval_id
         for update;
      assert_can_act(r_appr);
      if p_note is null then
         raise_application_error(-20108, 'Alasan penolakan wajib diisi.');
      end if;

      update apx_mbms_approvals
         set status   = k_rejected
            ,acted_by = apx_mbms_sec_pkg.app_user
            ,acted_on = sysdate
            ,note     = p_note
       where approval_id = p_approval_id;

      set_doc_status(get_type(r_appr.doc_type), r_appr.doc_id, k_rejected);
   end reject;

end apx_mbms_approval_pkg;
/
